commandLine.original:
python - <<'PY'
from pathlib import Path
import re
files = [
 ('001','dataset/run-001-normal/main.log'),
 ('002','dataset/run-002-normal/main_2.log'),
 ('003','dataset/run-003-normal/main_3.log'),
 ('004','dataset/run-004-normal/main_4.log'),
]
terms = ['Received proposal:', 'CollectVote(from', 'dispatching event for new view', 'OnNewView', 'Successfully updated HighQC', 'HighQC not updated', 'timeout', 'Timeout', 'DECIDE', 'CommitRule', 'TryCommit:', 'vote']
for label, name in files:
    counts = {term: 0 for term in terms}
    samples = {term: [] for term in terms}
    with open(name, errors='replace') as f:
        for n, line in enumerate(f, 1):
            for term in terms:
                if term.lower() in line.lower():
                    counts[term] += 1
                    if len(samples[term]) < 2: samples[term].append((n,line.rstrip()))
    print(f'\n=== {label} {name} ===')
    for term in terms:
        if counts[term]:
            print(f'{term}: {counts[term]}')
            for n,line in samples[term]: print(f'  {n}: {line}')
PY

