commandLine.original:
python3 - <<'PY'
import re
files=[('001','dataset/run-001-normal/main.log'),('002','dataset/run-002-normal/main_2.log'),('003','dataset/run-003-normal/main_3.log'),('004','dataset/run-004-normal/main_4.log')]
for tag,path in files:
    n=0; counters={'proposal':0,'dispatch':0,'highqc':0,'local_timeout':0,'decide':0,'commit':0}; maxvals={'proposal':-1,'cert':-1,'timeout':-1}; last=[]
    with open(path,errors='replace') as f:
        for n,line in enumerate(f,1):
            if 'Received proposal:' in line:
                counters['proposal']+=1
                m=re.search(r'view: (\d+)',line)
                if m:maxvals['proposal']=max(maxvals['proposal'],int(m.group(1)))
                m=re.search(r'QC\{ hash: .*?, view: (\d+)',line)
                if m:maxvals['cert']=max(maxvals['cert'],int(m.group(1)))
            if 'dispatching event for new view' in line:counters['dispatch']+=1
            if 'Successfully updated HighQC' in line:counters['highqc']+=1
            if 'OnLocalTimeout:' in line:
                counters['local_timeout']+=1
                m=re.search(r'OnLocalTimeout: (\d+)',line)
                if m:maxvals['timeout']=max(maxvals['timeout'],int(m.group(1)))
            if 'CommitRule - DECIDE:' in line:counters['decide']+=1
            if 'CommitRule - COMMIT:' in line:counters['commit']+=1
            if line.startswith('20'):last.append((n,line.rstrip()))
    print(tag, 'lines',n,'counts',counters,'max',maxvals)
    print(' last log:',last[-1][0],last[-1][1][-145:])
PY

